const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * A retirement is held while `retiredAt` is later than this instant, so it
 * is released at exactly `ORG_SLUG_HOLD_DAYS` after the rename.
 */
function holdCutoff(): IsoTimestamp {
  return toIsoTimestamp(
    new Date(Date.now() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY),
  );
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * The workspace a slug names: its current holder first, otherwise the
 * workspace that retired the slug while the hold lasts. Archived workspaces
 * resolve to nothing either way.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const current = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (current) return toOrganization(current);

  const retired = getDb()
    .select({ org: organizations })
    .from(organizationSlugRetirements)
    .innerJoin(
      organizations,
      eq(organizations.id, organizationSlugRetirements.orgId),
    )
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        gt(organizationSlugRetirements.retiredAt, holdCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return retired ? toOrganization(retired.org) : null;
}
