}''','''/**
 * Slugs a new workspace may not take: every current slug and every slug still
 * held by a retirement. Feeds `uniqueSlug()`; matching on the prefix keeps the
 * scan small.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const current = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const held = getDb()
    .select({ slug: organizationSlugRetirements.slug })
    .from(organizationSlugRetirements)
    .where(
      and(
        like(organizationSlugRetirements.slug, `${prefix}%`),
        gt(organizationSlugRetirements.retiredAt, holdCutoff()),
      ),
    )
    .all();
  return [...current, ...held].map((row) => row.slug);
}

/**
 * Whether `slug` may become `orgId`'s slug: no other workspace holds it as a
 * current slug, and no other workspace is still holding it as a retirement.
 * The workspace's own retirements never block it.
 */
export async function isOrgSlugAvailable(
  orgId: OrgId,
  slug: string,
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (holder) return false;

  const held = getDb()
    .select({ id: organizationSlugRetirements.id })
    .from(organizationSlugRetirements)
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        ne(organizationSlugRetirements.orgId, orgId),
        gt(organizationSlugRetirements.retiredAt, holdCutoff()),
      ),
    )
    .get();
  return held === undefined;
}

/**
 * Moves the workspace to `slug` and retires the slug it gives up, in one
 * transaction. Taking back a slug this workspace retired ends that retirement.
 * The caller checks availability first.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    tx.delete(organizationSlugRetirements)
      .where(
        and(
          eq(organizationSlugRetirements.orgId, orgId),
          eq(organizationSlugRetirements.slug, slug),
        ),
      )
      .run();

    tx.insert(organizationSlugRetirements)
      .values({
        id: newId(),
        orgId,
        slug: current.slug,
        retiredAt: stamp,
      })
      .run();

    return toOrganization(row);
  });
}''')
