/**
 * Workspace slug rename and the retirement hold (ADR 0005).
 */
import { afterAll, beforeAll, afterEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as organizationService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import * as activityService from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";
import type { SessionPrincipal } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

const DAY_MS = 24 * 60 * 60 * 1000;

function principalFor(userId: string): SessionPrincipal {
  return {
    userId: userId as SessionPrincipal["userId"],
    email: "owner@test.example",
    activeOrgId: null,
    expiresAt: new Date(Date.now() + DAY_MS).toISOString() as SessionPrincipal["expiresAt"],
  };
}

describe("services/organization-service renameOrganizationSlug", () => {
  it("moves the workspace to the new slug and keeps the old one for the hold", async () => {
    const tenant = await createTenant("rename-basic", "growth");

    const renamed = await organizationService.renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rename-basic-new",
    });

    expect(renamed).toMatchObject({ id: tenant.org.id, slug: "rename-basic-new", name: tenant.org.name });
    expect((await orgRepo.findOrgBySlug("rename-basic-new"))?.id).toBe(tenant.org.id);
    expect((await orgRepo.findOrgBySlug("rename-basic"))?.id).toBe(tenant.org.id);

    const resolved = await resolveActorForOrg(principalFor(tenant.userIds.member), "rename-basic");
    expect(resolved).toMatchObject({ orgId: tenant.org.id, role: "member" });
  });

  it("publishes organization.slug_changed once and audits it with both slugs", async () => {
    const tenant = await createTenant("rename-event", "growth");
    const seen: unknown[] = [];
    const off: Unsubscribe = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    try {
      await organizationService.renameOrganizationSlug(tenant.actors.admin, {
        orgId: tenant.org.id,
        slug: "rename-event-new",
      });
    } finally {
      off();
    }

    expect(seen).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.admin,
        from: "rename-event",
        to: "rename-event-new",
      }),
    ]);

    const page = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rename-event", to: "rename-event-new" },
    });
  });

  it("does nothing when renaming to the current slug", async () => {
    const tenant = await createTenant("rename-same", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });

    try {
      const org = await organizationService.renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "rename-same",
      });
      expect(org.slug).toBe("rename-same");
    } finally {
      off();
    }

    expect(seen).toHaveLength(0);
    const page = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(0);
  });

  it("refuses a slug another workspace holds, and never suffixes it", async () => {
    const taken = await createTenant("rename-taken-holder", "growth");
    const tenant = await createTenant("rename-taken-mover", "growth");

    await expect(
      organizationService.renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: taken.org.slug,
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

