    });
    expect(taken.slug).toBe("rename-release");
  });

  it("creation suffixes a slug that is still held", async () => {
    const tenant = await createTenant("rename-create-held", "growth");
    await organizationService.renameOrganizationSlug(tenant.actors.owner, {
